#include "gemm.cuh"

#include <cuda_runtime.h>

// =============================================================================
//  High-throughput tiled GEMM for NVIDIA Ampere (A40, sm_86).
//
//  - Thread block computes a BM x BN tile of C.
//  - Each thread owns an 8x8 register micro-tile (TM x TN accumulators) for
//    strong ILP and register re-use.
//  - B is staged in shared memory TRANSPOSED (sBt[k][col]) so the inner loop
//    reads consecutive shared banks (conflict-free); A rows broadcast.
//  - Global loads use 16B float4 vector transactions on the aligned fast path.
//
//  Boundary handling: a block is "fast" iff the whole tile lies inside [0,N)
//  and N is a multiple of 8 (so every k-slab and every row is 16B aligned).
//  Fast blocks run guard-free. Edge blocks (and any odd N) fall back to a
//  masked scalar load/store so the kernel is correct for arbitrary N. This
//  keeps overhead zero for tile-aligned workloads while staying exact.
// =============================================================================

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define TPBX (BN / TN)   // 16
#define TPBY (BM / TM)   // 16
#define TPB (TPBX * TPBY) // 256 threads

__global__ void gemmKernel(const float* __restrict__ A, const float* __restrict__ B,
                           float* __restrict__ C, int N) {
    __shared__ float sA[BM][BK];
    __shared__ float sBt[BK][BN];

    const int tid = threadIdx.y * TPBX + threadIdx.x;  // 0..255
    const int bx = blockIdx.x, by = blockIdx.y;

    const int mtRow = threadIdx.y;   // 0..15
    const int mtCol = threadIdx.x;   // 0..15

    const int gRow0 = by * BM + mtRow * TM;
    const int gCol0 = bx * BN + mtCol * TN;

    // Is this block entirely interior (and aligned)? Then no guards needed.
    const bool fast = (N % 8 == 0) && (by * BM + BM <= N) && (bx * BN + BN <= N);

    float acc[TM][TN];
#pragma unroll
    for (int r = 0; r < TM; ++r)
#pragma unroll
        for (int c = 0; c < TN; ++c) acc[r][c] = 0.0f;

    const int numTiles = (N + BK - 1) / BK;

    for (int t = 0; t < numTiles; ++t) {
        const int k0 = t * BK;

        if (fast) {
            // ---- aligned vectorized global -> shared ----
            // A tile: BM*BK = 1024 elements = 256 float4 (BK=8 => 2/row).
            {
                const int base = tid * 4;
                const int rowIn = base >> 3;          // base / 8
                const int cOfs = base - (rowIn << 3); // 0 or 4
                const float4 v = *reinterpret_cast<const float4*>(
                    &A[(by * BM + rowIn) * N + (k0 + cOfs)]);
                *reinterpret_cast<float4*>(&sA[rowIn][cOfs]) = v;
            }
            // B tile: BK*BN = 1024 elements = 256 float4, stored transposed.
            {
                const int f4 = tid;
                const int kk = f4 >> 5;               // / (BN/4) = /32
                const int col4 = f4 - (kk << 5);
                const int c0 = col4 << 2;
                const float4 v = *reinterpret_cast<const float4*>(
                    &B[(k0 + kk) * N + (bx * BN + c0)]);
                *reinterpret_cast<float4*>(&sBt[kk][c0]) = v;
            }
        } else {
            // ---- masked scalar global -> shared (zero-fill out of range) ----
            const int base = tid << 2;
#pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int idx = base + q;
                if (idx < BM * BK) {
                    const int i = idx >> 3;
                    const int j = idx - (i << 3);
                    const int gi = by * BM + i;
                    const int gj = k0 + j;
                    sA[i][j] = (gi < N && gj < N) ? A[gi * N + gj] : 0.0f;
                }
            }
            const int base2 = tid << 2;
#pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int idx = base2 + q;
                if (idx < BK * BN) {
                    const int kk = idx >> 7;          // / BN
                    const int c = idx - (kk << 7);    // % BN
                    const int gk = k0 + kk;
                    const int gc = bx * BN + c;
                    sBt[kk][c] = (gk < N && gc < N) ? B[gk * N + gc] : 0.0f;
                }
            }
        }

        __syncthreads();

#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a[TM];
            float b[TN];
#pragma unroll
            for (int r = 0; r < TM; ++r) a[r] = sA[mtRow * TM + r][k];
#pragma unroll
            for (int c = 0; c < TN; ++c) b[c] = sBt[k][mtCol * TN + c];
#pragma unroll
            for (int r = 0; r < TM; ++r)
#pragma unroll
                for (int c = 0; c < TN; ++c) acc[r][c] += a[r] * b[c];
        }

        __syncthreads();
    }

    // ---- store micro-tile to C ----
    if (fast) {
#pragma unroll
        for (int r = 0; r < TM; ++r) {
            float *out = &C[(gRow0 + r) * N + gCol0];
            *reinterpret_cast<float4*>(out) =
                make_float4(acc[r][0], acc[r][1], acc[r][2], acc[r][3]);
            *reinterpret_cast<float4*>(&out[4]) =
                make_float4(acc[r][4], acc[r][5], acc[r][6], acc[r][7]);
        }
    } else {
#pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int gr = gRow0 + r;
            if (gr >= N) break;
            const long cbase = (long)gr * N + gCol0;
#pragma unroll
            for (int c = 0; c < TN; ++c)
                if (gCol0 + c < N) C[cbase + c] = acc[r][c];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(TPBX, TPBY);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

