#include "gemm.cuh"

#include <cuda_runtime.h>

// =============================================================================
//  High-throughput tiled GEMM for NVIDIA Ampere (A40, sm_86).
//
//  Design:
//    - Thread-block computes a BM x BN tile of C.
//    - Each thread owns an 8x8 register micro-tile (64 accumulators), giving
//      good ILP and re-use; BK=8 is the shared-memory k-slab.
//    - Global loads use float4 (16B) vector transactions.
//    - B is staged in shared memory TRANSPOSED (sBt[k][col]) so the inner loop
//      reads consecutive banks and avoids conflicts.
//    - Because the inputs are pre-padded on the host side (stride a multiple of
//      128, zero-filled beyond N), every global load lands in-bounds and 16B
//      aligned, so the hot path needs no boundary predicates at all. The final
//      C store is the only place that guards against `N`.
// =============================================================================

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define TPBX (BN / TN)   // 16
#define TPBY (BM / TM)   // 16
#define TPB (TPBX * TPBY) // 256 threads

// --- pre-padding (row stride multiple of 128 => 16B aligned & zero-filled) ---

__global__ void zeroFillKernel(float* p, long n) {
    long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) p[i] = 0.0f;
}

__global__ void copyPadKernel(const float* __restrict__ src, float* __restrict__ dst,
                              int N, int padN) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * N) {
        int r = idx / N;
        int c = idx - r * N;
        dst[(long)r * padN + c] = src[idx];
    }
}

// --- main GEMM kernel (operates on pre-padded, aligned A/B) -----------------

__global__ void gemmKernel(const float* __restrict__ A, const float* __restrict__ B,
                           float* __restrict__ C, int N, int padN) {
    __shared__ float sA[BM][BK];
    __shared__ float sBt[BK][BN];

    const int tid = threadIdx.y * TPBX + threadIdx.x;  // 0..255
    const int bx = blockIdx.x, by = blockIdx.y;

    // micro-tile origin within the block for this thread
    const int mtRow = threadIdx.y;   // 0..15 -> row*TM
    const int mtCol = threadIdx.x;   // 0..15 -> col*TN

    // global micro-tile origin
    const int gRow0 = by * BM + mtRow * TM;
    const int gCol0 = bx * BN + mtCol * TN;

    float acc[TM][TN];
#pragma unroll
    for (int r = 0; r < TM; ++r)
#pragma unroll
        for (int c = 0; c < TN; ++c) acc[r][c] = 0.0f;

    const int numTiles = padN / BK;  // padN is a multiple of BM=128, hence of BK

    for (int t = 0; t < numTiles; ++t) {
        const int k0 = t * BK;

        // ---- stage A tile (BM x BK) into shared ----
        // 1024 elements / 256 threads = 1 float4 each (BK=8 => 2 float4/row).
        {
            const int base = tid * 4;           // flat element offset in the tile
            const int rowIn = base / BK;        // 0..BM-1
            const int cOfs = base - rowIn * BK; // 0 or 4
            const float4 v = *reinterpret_cast<const float4*>(
                &A[(long)(by * BM + rowIn) * padN + (k0 + cOfs)]);
            *reinterpret_cast<float4*>(&sA[rowIn][cOfs]) = v;
        }

        // ---- stage B tile (BK x BN), transposed into shared ----
        // 1024 elements / 256 threads = 1 float4 each.
        {
            const int f4 = tid;                    // which float4 (0..BK*(BN/4)-1)
            const int kk = f4 / (BN / 4);          // 0..BK-1
            const int col4 = f4 - kk * (BN / 4);   // 0..(BN/4)-1
            const int c0 = col4 * 4;
            const float4 v = *reinterpret_cast<const float4*>(
                &B[(long)(k0 + kk) * padN + (bx * BN + c0)]);
            *reinterpret_cast<float4*>(&sBt[kk][c0]) = v;
        }

        __syncthreads();

#pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a[TM];
            float b[TN];
#pragma unroll
            for (int r = 0; r < TM; ++r) a[r] = sA[mtRow * TM + r][k];
#pragma unroll
            for (int c = 0; c < TN; ++c) b[c] = sBt[k][mtCol * TN + c];
#pragma unroll
            for (int r = 0; r < TM; ++r)
#pragma unroll
                for (int c = 0; c < TN; ++c) acc[r][c] += a[r] * b[c];
        }

        __syncthreads();
    }

    // ---- store micro-tile to C (only legal elements; vectorized when safe) ----
#pragma unroll
    for (int r = 0; r < TM; ++r) {
        const int gr = gRow0 + r;
        if (gr >= N) break;
        const int gc = gCol0;
        // scalar guarded store for the 8 columns (simple & exact)
        const long cbase = (long)gr * N + gc;
#pragma unroll
        for (int c = 0; c < TN; ++c)
            if (gc + c < N) C[cbase + c] = acc[r][c];
    }
}

// Cached, padded device scratch for A and B.
static float* g_pA = nullptr;
static float* g_pB = nullptr;
static int  g_padN = 0;

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;

    const int padN = ((N + BM - 1) / BM) * BM;  // row stride: multiple of BM>=128

    if (padN != g_padN) {
        if (g_pA) { cudaFree(g_pA); cudaFree(g_pB); g_pA = g_pB = nullptr; }
        if (padN) {
            cudaMalloc(&g_pA, (size_t)padN * padN * sizeof(float));
            cudaMalloc(&g_pB, (size_t)padN * padN * sizeof(float));
        }
        g_padN = padN;
    }

    const size_t plane = (size_t)padN * padN;
    cudaMemset(g_pA, 0, plane * sizeof(float));
    cudaMemset(g_pB, 0, plane * sizeof(float));

    const int nt = 256;
    const int blocks = (N * N + nt - 1) / nt;

    // copy A and B into their zero-padded tiles (coalesced)
    zeroFillKernel<<<(int)((plane + nt - 1) / nt), nt>>>(g_pA, (long)plane);
    zeroFillKernel<<<(int)((plane + nt - 1) / nt), nt>>>(g_pB, (long)plane);
    copyPadKernel<<<blocks, nt>>>(dA, g_pA, N, padN);
    copyPadKernel<<<blocks, nt>>>(dB, g_pB, N, padN);

    dim3 block(TPBX, TPBY);
    dim3 grid(padN / BN, padN / BM);
    gemmKernel<<<grid, block>>>(g_pA, g_pB, dC, N, padN);
}

