#include <cstdlib>
#include "src/gemm.cuh"

#define CK(c) do{cudaError_t e=(c);if(e!=cudaSuccess){printf("ERR %s %d\n",cudaGetErrorString(e),__LINE__);exit(1);}}while(0)

int main(int argc,char**argv){
    int N = argc>1?atoi(argv[1]):2048;
    printf("N=%d\n",N);
    size_t b=(size_t)N*N*sizeof(float);
    float*dA,*dB,*dC; CK(cudaMalloc(&dA,b));CK(cudaMalloc(&dB,b));CK(cudaMalloc(&dC,b));
    CK(cudaMemset(dA,0,b));CK(cudaMemset(dB,0,b));
    cudaEvent_t e0,e1;cudaEventCreate(&e0);cudaEventCreate(&e1);
    double best=1e30;
    for(int it=0;it<20;it++){
        cudaEventRecord(e0); launchGemm(dA,dB,dC,N); cudaEventRecord(e1);
        cudaEventSynchronize(e1);float ms;cudaEventElapsedTime(&ms,e0,e1);
        if(ms<best)best=ms;
    }
    double g=2.0*(double)N*N*N/best/1e9;
    printf("mine:    %.3f ms  %.2f TFLOP/s\n",best,g);
    // cublas
    cublasHandle_t h;cublasCreate(&h);
    float alpha=1.f,beta=0.f;
    best=1e30;
    for(int it=0;it<20;it++){
