    }
    g=2.0*(double)N*N*N/best/1e9;
    printf("cublas:  %.3f ms  %.2f TFLOP/s\n",best,g);
    printf("ratio: %.3f\n", (best>0? (2.0*(double)N*N*N/best/1e9):0)/(2.0*(double)N*N*N/(best>0?best:1)/1e9) );
    return 0;
}

