__global__ void __launch_bounds__(TPB, 2)
gemmKernel(const float* __restrict__ A, const float* __restrict__ B,
           float* __restrict__ C, int N) {
    __shared__ float sA[BUF][BM][BK];
    __shared__ float sB[BUF][BK][BN];

