        for (int t = 0; t < numTiles; ++t) {
            if (t + 1 < numTiles) {
                asyncLoadA(A, sA, t + 1, (t + 1) & 1, tid, bx, by, N);
                asyncLoadB(B, sB, t + 1, (t + 1) & 1, tid, bx, N);
                __pipeline_commit();
            }
            __pipeline_wait_prior(1);   // tile t's group is the oldest; ensure it landed
            __syncthreads();

            const int buf = t & 1;
#pragma unroll
            for (int k = 0; k < BK; ++k) {
                float a[TM];
                float b[TN];
#pragma unroll
                for (int r = 0; r < TM; ++r) a[r] = sA[buf][mtRow * TM + r][k];
#pragma unroll
                for (int c = 0; c < TN; ++c) b[c] = sB[buf][k][mtCol * TN + c];
