                }
            }
            const int base2 = tid << 2;
#pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int idx = base2 + q;
                if (idx < BK * BN) {
                    const int kk = idx >> 7;               // / BN
                    const int c = idx - (kk << 7);         // % BN
                    const int gk = k0 + kk;
