#include "gemm.cuh"

#include <cuda_runtime.h>
#include <cuda_pipeline.h>

// =============================================================================
//  High-throughput tiled GEMM for NVIDIA Ampere (A40, sm_86).
//
//  - Thread block computes a BM x BN tile of C; each thread owns an 8x8
//    register micro-tile (TM x TN accumulators) for ILP and register re-use.
//  - B is staged in shared memory TRANSPOSED (sB[k][col]) so the inner loop
//    reads consecutive shared banks (conflict-free); A rows broadcast.
//  - Global->shared staging uses cp.async (Ampere) with DOUBLE buffering, so
//    loads for tile t+1 overlap the compute of tile t and hide global latency.
//  - "fast" blocks (tile fully interior and N a multiple of BK) run guard-free;
//    edge / odd-N blocks use a masked scalar path so the kernel is exact for
//    arbitrary N with zero fast-path overhead.
// =============================================================================

#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8
#define TPBX (BN / TN)   // 16
#define TPBY (BM / TM)   // 16
#define TPB (TPBX * TPBY) // 256 threads
#define BUF 2            // double buffer

// Stage a BM x BK slab of A into shared via cp.async (16B/thread x2).
__device__ __forceinline__ void asyncLoadA(
        const float* __restrict__ A, float (*sA)[BM][BK],
        int tile, int buf, int tid, int bx, int by, int N) {
    const int k0 = tile * BK;
#pragma unroll
    for (int v = 0; v < 2; ++v) {
        const int j = tid + v * TPB;         // 0..511 -> BM*(BK/4) float4s
        const int row = j >> 2;              // 0..BM-1
        const int c4 = j & 3;                // 0..BK/4-1
        const int c0 = c4 << 2;
        __pipeline_memcpy_async(&sA[buf][row][c0],
                                &A[(by * BM + row) * N + (k0 + c0)], 16);
    }
}

// Stage a BK x BN slab of B (transposed) into shared via cp.async.
__device__ __forceinline__ void asyncLoadB(
        const float* __restrict__ B, float (*sB)[BK][BN],
        int tile, int buf, int tid, int bx, int N) {
    const int k0 = tile * BK;
#pragma unroll
    for (int v = 0; v < 2; ++v) {
        const int f = tid + v * TPB;         // 0..511 -> BK*(BN/4) float4s
        const int kk = f >> 5;               // / (BN/4) = /32
        const int c4 = f & 31;
        const int c0 = c4 << 2;
        __pipeline_memcpy_async(&sB[buf][kk][c0],
                                &B[(k0 + kk) * N + (bx * BN + c0)], 16);
    }
}

