#include "gemm.cuh"

#include <cuda_runtime.h>
#include <cuda_pipeline.h>

// =============================================================================
//  High-throughput tiled GEMM for NVIDIA Ampere (A40, sm_86).
//  Configurable tile / register-block so the occupancy/perf sweet spot can be
//  found per-architecture. Defaults target a high-occupancy configuration.
//
//  - Thread block computes a BM x BN tile of C; each thread owns a TM x TN
//    register micro-tile of accumulators.
//  - B is staged in shared memory TRANSPOSED (sB[k][col]) so the inner loop
//    reads consecutive shared banks (conflict-free); A rows broadcast.
//  - Global->shared staging uses cp.async (Ampere) with DOUBLE buffering, so
//    loads for tile t+1 overlap compute of tile t and hide global latency.
//  - "fast" blocks (tile fully interior and N a multiple of BK, so every load
//    is legal and 16B aligned) run guard-free. Edge / odd-N blocks fall back
//    to a masked scalar path, keeping the kernel exact for arbitrary N.
// =============================================================================

#ifndef BM
#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4
#define MINBLK 4
#endif

#define TPBX (BN / TN)
#define TPBY (BM / TM)
#define TPB (TPBX * TPBY)
#define BUF 2

__device__ __forceinline__ void asyncLoadA(
        const float* __restrict__ A, float (*sA)[BM][BK],
        int tile, int buf, int tid, int by, int N) {
    const int k0 = tile * BK;
    const int per = BM * BK / (4 * TPB);          // float4s per thread
    const int cols4 = BK / 4;
#pragma unroll
    for (int v = 0; v < per; ++v) {
        const int e = v * TPB + tid;              // float4 index
        const int row = e / cols4;
        const int c4 = e - row * cols4;
        const int c0 = c4 << 2;
        __pipeline_memcpy_async(&sA[buf][row][c0],
                                &A[(by * BM + row) * N + (k0 + c0)], 16);
    }
}

__device__ __forceinline__ void asyncLoadB(
        const float* __restrict__ B, float (*sB)[BK][BN],
        int tile, int buf, int tid, int bx, int N) {
    const int k0 = tile * BK;
    const int per = BK * BN / (4 * TPB);
    const int cols4 = BN / 4;
#pragma unroll
    for (int v = 0; v < per; ++v) {
        const int e = v * TPB + tid;
        const int kk = e / cols4;
        const int c4 = e - kk * cols4;
        const int c0 = c4 << 2;
        __pipeline_memcpy_async(&sB[buf][kk][c0],
                                &B[(k0 + kk) * N + (bx * BN + c0)], 16);
    }
}

__global__ void __launch_bounds__(TPB, MINBLK)
gemmKernel(const float* __restrict__ A, const float* __restrict__ B,
           float* __restrict__ C, int N) {
    __shared__ float sA[BUF][BM][BK];
    __shared__ float sB[BUF][BK][BN];

    const int tid = threadIdx.y * TPBX + threadIdx.x;
    const int bx = blockIdx.x, by = blockIdx.y;
    const int mtRow = threadIdx.y, mtCol = threadIdx.x;
    const int gRow0 = by * BM + mtRow * TM;
    const int gCol0 = bx * BN + mtCol * TN;

    const bool fast = (N % BK == 0) && (by * BM + BM <= N) && (bx * BN + BN <= N);

    float acc[TM][TN];
#pragma unroll
    for (int r = 0; r < TM; ++r)
#pragma unroll
        for (int c = 0; c < TN; ++c) acc[r][c] = 0.0f;

    const int numTiles = (N + BK - 1) / BK;

    if (fast) {
        asyncLoadA(A, sA, 0, 0, tid, by, N);
        asyncLoadB(B, sB, 0, 0, tid, bx, N);
        __pipeline_commit();

        for (int t = 0; t < numTiles; ++t) {
            if (t + 1 < numTiles) {
                asyncLoadA(A, sA, t + 1, (t + 1) & 1, tid, by, N);
                asyncLoadB(B, sB, t + 1, (t + 1) & 1, tid, bx, N);
                __pipeline_commit();
            }
            __pipeline_wait_prior(1);
            __syncthreads();

            const int buf = t & 1;
#pragma unroll
            for (int k = 0; k < BK; ++k) {
                float a[TM];
                float b[TN];
#pragma unroll
                for (int r = 0; r < TM; ++r) a[r] = sA[buf][mtRow * TM + r][k];
#pragma unroll
                for (int c = 0; c < TN; ++c) b[c] = sB[buf][k][mtCol * TN + c];
#pragma unroll
                for (int r = 0; r < TM; ++r)
#pragma unroll
                    for (int c = 0; c < TN; ++c) acc[r][c] += a[r] * b[c];
            }
            __syncthreads();
        }

