                    const int c = idx - kk * BN;
                    const int gk = k0 + kk;
                    const int gc = bx * BN + c;
                    sB[0][kk][c] = (gk < N && gc < N) ? B[gk * N + gc] : 0.0f;
                }
            }
            __syncthreads();
#pragma unroll
            for (int k = 0; k < BK; ++k) {
                float a[TM];
                float b[TN];
#pragma unroll
                for (int r = 0; r < TM; ++r) a[r] = sA[0][mtRow * TM + r][k];
#pragma unroll
                for (int c = 0; c < TN; ++c) b[c] = sB[0][k][mtCol * TN + c];
#pragma unroll
                for (int r = 0; r < TM; ++r)
#pragma unroll
                    for (int c = 0; c < TN; ++c) acc[r][c] += a[r] * b[c];
            }
            __syncthreads();
        }
#pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int gr = gRow0 + r;
            if (gr >= N) break;
            const long cbase = (long)gr * N + gCol0;
#pragma unroll
            for (int c = 0; c < TN; ++c)
                if (gCol0 + c < N) C[cbase + c] = acc[r][c];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(TPBX, TPBY);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

