#pragma unroll
            for (int r = 0; r < TM; ++r) {
                float* out = &C[(gRow0 + r) * N + gCol0];
                *reinterpret_cast<float4*>(out) =
                    make_float4(acc[r][0], acc[r][1], acc[r][2], acc[r][3]);
            }
        } else {
#pragma unroll
            for (int r = 0; r < TM; ++r)
#pragma unroll
                for (int c = 0; c < TN; ++c)
                    C[(gRow0 + r) * N + gCol0 + c] = acc[r][c];
        }
    } else {
        const int count = BM * BK;
        for (int t = 0; t < numTiles; ++t) {
            const int k0 = t * BK;
            const int base = tid << 3;
#pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int idx = base + q;
                if (idx < count) {
                    const int i = idx / BK;
                    const int j = idx - i * BK;
                    const int gi = by * BM + i;
                    const int gj = k0 + j;
                    sA[0][i][j] = (gi < N && gj < N) ? A[gi * N + gj] : 0.0f;
                }
            }
            const int base2 = tid << 3;
#pragma unroll
            for (int q = 0; q < 8; ++q) {
                const int idx = base2 + q;
                if (idx < BK * BN) {
                    const int kk = idx / BN;
                    const int c = idx - kk * BN;
                    const int gk = k0 + kk;
                    const int gc = bx * BN + c;
                    sB[0][kk][c] = (gk < N && gc < N) ? B[gk * N + gc] : 0.0f;
                }
            }
            __syncthreads();
#pragma unroll
            for (int k = 0; k < BK; ++k) {
                float a[TM];
                float b[TN];
#pragma unroll
                for (int r = 0; r < TM; ++r) a[r] = sA[0][mtRow * TM + r][k];
#pragma unroll
                for (int c = 0; c < TN; ++c) b[c] = sB[0][k][mtCol * TN + c];
#pragma unroll
                for (int r = 0; r < TM; ++r)
#pragma unroll
                    for (int c = 0; c < TN; ++c) acc[r][c] += a[r] * b[c];
            }
            __syncthreads();
        }
#pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int gr = gRow0 + r;
            if (gr >= N) break;
            const long cbase = (long)gr * N + gCol0;
#pragma unroll
            for (int c = 0; c < TN; ++c)
                if (gCol0 + c < N) C[cbase + c] = acc[r][c];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(TPBX, TPBY);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
